/**
 * Built-in model price table, in USD per 1,000,000 tokens.
 *
 * Standard-tier list prices as of **2026-06** (sourced from each provider's
 * pricing page - see README). Notes:
 *  - Prices are the base / standard tier. Long-context (>200k) tiers, "pro",
 *    batch, flex, and priority tiers are intentionally omitted for simplicity.
 *  - Cache-read pricing is ~0.1x input and cache-write ~1.25x input across all
 *    four labs, so we omit per-model cache fields and use those defaults (see
 *    `Pricing.estimateUsage`). Override if your contract differs.
 *  - Every number here is overridable: pass your own {@link ModelPrice}[] to
 *    `audit(trace, { models })`. The $/ms savings estimates are only as
 *    credible as this table, so keeping it user-configurable is deliberate.
 */

/** Relative capability tier, used by the model-tier-mismatch audit. */
export type ModelTier = 'frontier' | 'mid' | 'small'

/** Pricing for one model, USD per 1M tokens. */
export interface ModelPrice {
  /** Canonical model id. */
  id: string
  /** Provider / system. */
  provider: string
  /** USD per 1M input (prompt) tokens. */
  input: number
  /** USD per 1M output (completion) tokens. */
  output: number
  /** USD per 1M cached-read tokens. Defaults to 0.1x input when omitted. */
  cachedInput?: number
  /** USD per 1M cache-write tokens. Defaults to 1.25x input when omitted. */
  cacheWrite?: number
  /** Capability tier. */
  tier: ModelTier
  /** A cheaper model with comparable capability for trivial steps, if any. */
  cheaperAlternative?: string
  /** Extra match patterns (substrings) that should resolve to this entry. */
  aliases?: string[]
}

