import { describe, it, expect } from 'vitest'
import { Pricing, normalizeModelId } from './index.js'
import { llm } from '../../test/helpers.js'

describe('normalizeModelId', () => {
  it('strips provider prefixes and date/latest suffixes', () => {
    expect(normalizeModelId('anthropic.claude-opus-4-8')).toBe('claude-opus-4-8')
    expect(normalizeModelId('claude-opus-4-8-20250101')).toBe('claude-opus-4-8')
    expect(normalizeModelId('GPT-4o')).toBe('gpt-4o')
    expect(normalizeModelId('gemini-1.5-pro-latest')).toBe('gemini-1.5-pro')
  })
})

describe('Pricing', () => {
  const p = new Pricing()

  it('resolves exact, dated, and prefixed model ids', () => {
    expect(p.find('claude-opus-4-8')?.id).toBe('claude-opus-4-8')
    expect(p.find('claude-opus-4-8-20250101')?.id).toBe('claude-opus-4-8')
    expect(p.find('anthropic.claude-sonnet-4-6')?.id).toBe('claude-sonnet-4-6')
    expect(p.find('gpt-4o-mini')?.tier).toBe('small')
  })

  it('resolves aliases to the canonical priced model', () => {
    expect(p.find('claude-3-5-haiku')?.id).toBe('claude-haiku-4-5')
    expect(p.find('gpt-4-turbo')?.id).toBe('gpt-4o')
  })

  it('returns undefined for unknown models', () => {
    expect(p.find('totally-made-up-model')).toBeUndefined()
    expect(p.find(undefined)).toBeUndefined()
  })

  it('estimates cost from token usage', () => {
    // 1M input @ $5 + 1M output @ $25 = $30 on opus-4-8
    expect(p.estimateUsage({ input: 1_000_000, output: 1_000_000 }, 'claude-opus-4-8')).toBeCloseTo(30, 6)
  })

  it('prices cached reads at 0.1x input by default', () => {
    // 1M cache-read tokens on opus ($5 input) -> $0.50
    expect(p.estimateUsage({ cacheRead: 1_000_000 }, 'claude-opus-4-8')).toBeCloseTo(0.5, 6)
  })

  it('prices cache writes at 1.25x input by default', () => {
    expect(p.estimateUsage({ cacheWrite: 1_000_000 }, 'claude-opus-4-8')).toBeCloseTo(6.25, 6)
  })

  it('returns 0 estimate for unknown models', () => {
    expect(p.estimateUsage({ input: 1_000_000 }, 'mystery-model')).toBe(0)
  })

  it('costOf prefers a source-reported cost over estimation', () => {
    expect(p.costOf(llm({ cost: 0.123, usage: { input: 1_000_000 } }))).toBe(0.123)
    expect(p.costOf(llm({ usage: { input: 1_000_000, output: 0 }, model: 'claude-opus-4-8' }))).toBeCloseTo(5, 6)
  })

  it('exposes tier and cheaper alternatives', () => {
    expect(p.tierOf('claude-opus-4-8')).toBe('frontier')
    expect(p.cheaperAlternative('claude-opus-4-8')?.id).toBe('claude-sonnet-4-6')
    expect(p.cheaperAlternative('claude-haiku-4-5')).toBeUndefined()
  })

  it('resolves current frontier-lab models (2026)', () => {
    expect(p.find('gpt-5.5')).toMatchObject({ provider: 'openai', input: 5, output: 30, tier: 'frontier' })
    expect(p.find('gpt-5.4-mini')).toMatchObject({ input: 0.75, output: 4.5, tier: 'mid' })
    expect(p.find('gemini-3.1-pro')).toMatchObject({ provider: 'google', input: 2, output: 12, tier: 'frontier' })
    expect(p.find('gemini-3.5-flash')).toMatchObject({ input: 1.5, output: 9 })
    expect(p.find('grok-4.3')).toMatchObject({ provider: 'xai', input: 1.25, output: 2.5 })
  })

  it('resolves preview suffixes and family aliases to current models', () => {
    expect(p.find('gemini-3.1-pro-preview')?.id).toBe('gemini-3.1-pro')
    expect(p.find('gpt-5')?.id).toBe('gpt-5.5')
    expect(p.find('grok-4-fast')?.id).toBe('grok-4.3')
    expect(p.find('gemini-1.5-pro')?.id).toBe('gemini-2.5-pro') // legacy id → nearest entry
  })

  it('suggests cheaper tiers for the new flagships', () => {
    expect(p.cheaperAlternative('gpt-5.5')?.id).toBe('gpt-5.4-mini')
    expect(p.cheaperAlternative('gemini-3.1-pro')?.id).toBe('gemini-3.5-flash')
  })

  it('accepts a custom model table', () => {
    const custom = new Pricing([
      { id: 'my-model', provider: 'me', input: 100, output: 200, tier: 'frontier' },
    ])
    expect(custom.estimateUsage({ input: 1_000_000 }, 'my-model')).toBe(100)
    expect(custom.find('claude-opus-4-8')).toBeUndefined()
  })
})

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { detect, parse } from './vercel.js'
import { totalTokens, llmSpans, toolSpans } from '../../trace/index.js'

const here = dirname(fileURLToPath(import.meta.url))
const fixture = JSON.parse(readFileSync(join(here, '../../../test/fixtures/vercel-ai-sdk.json'), 'utf8'))

describe('vercel AI SDK adapter', () => {
  it('detects ai.* OTLP traces', () => {
    expect(detect(fixture)).toBe(true)
    expect(detect({ resourceSpans: [] })).toBe(false)
  })

  it('treats doGenerate leaves as LLM calls and wrappers as chains', () => {
    const run = parse(fixture)
    expect(run.source).toBe('vercel')
    expect(llmSpans(run)).toHaveLength(2)
    expect(run.spans.filter((s) => s.kind === 'chain')).toHaveLength(1)
  })

  it('does not double-count tokens between wrapper and leaf spans', () => {
    const run = parse(fixture)
    // only the two doGenerate leaves count: (1000+100) + (1200+80)
    expect(totalTokens(run)).toBe(2380)
  })

  it('normalizes provider and model', () => {
    const run = parse(fixture)
    const llm = llmSpans(run)[0]!
    expect(llm.model).toBe('gpt-4o')
    expect(llm.provider).toBe('openai')
  })

  it('extracts tool calls with args and result', () => {
    const run = parse(fixture)
    const tools = toolSpans(run)
    expect(tools).toHaveLength(1)
    expect(tools[0]!.toolName).toBe('get_weather')
    expect(tools[0]!.input).toBe('{"city":"Paris"}')
    expect(tools[0]!.output).toBe('18C sunny')
  })

  it('falls back to wrapper spans as LLM when no doGenerate leaves exist', () => {
    const onlyWrapper = {
      resourceSpans: [
        {
          resource: { attributes: [] },
          scopeSpans: [
            {
              scope: { name: 'ai' },
              spans: [
                {
                  spanId: 'w1',
                  name: 'ai.generateText',
                  startTimeUnixNano: '1000000',
                  endTimeUnixNano: '2000000',
                  attributes: [
                    { key: 'ai.model.id', value: { stringValue: 'gpt-4o-mini' } },
                    { key: 'ai.usage.promptTokens', value: { intValue: '500' } },
                    { key: 'ai.usage.completionTokens', value: { intValue: '50' } },
                  ],
                },
              ],
            },
          ],
        },
      ],
    }
    const run = parse(onlyWrapper)
    expect(llmSpans(run)).toHaveLength(1)
    expect(totalTokens(run)).toBe(550)
  })
})

