import type { Audit, AuditResult, Finding } from '../types.js'
import { llmSpans } from '../../trace/index.js'
import { clamp01, round, runCost } from '../util.js'

/**
 * Flags trivial LLM steps (tiny input and output - routing, classification,
 * yes/no decisions) that ran on a frontier-tier model where a cheaper model
 * with comparable capability would do. Savings = the per-call cost delta.
 */
export const modelTierMismatch: Audit = ({ run, pricing, thresholds }): AuditResult => {
  const total = runCost(run, pricing)
  const findings: Finding[] = []
  let saved = 0

  for (const span of llmSpans(run)) {
    if (pricing.tierOf(span.model) !== 'frontier') continue
    const usage = span.usage
    if (!usage || usage.output === undefined) continue
    const trivial =
      usage.output <= thresholds.trivialOutputTokens &&
      (usage.input === undefined || usage.input <= thresholds.trivialInputTokens)
    if (!trivial) continue

    const cheaper = pricing.cheaperAlternative(span.model)
    if (!cheaper) continue
    const current = pricing.costOf(span)
    const alt = pricing.estimateUsage(usage, cheaper.id)
    const delta = current - alt
    if (delta <= 0) continue

    saved += delta
    findings.push({
      message: `Trivial step (${usage.input ?? '?'}→${usage.output} tokens) used \`${span.model}\`; \`${cheaper.id}\` would handle it for ~$${round(delta)} less.`,
      spanIds: [span.id],
      savings: { usd: round(delta) },
    })
  }

  const score = total > 0 ? clamp01(1 - saved / total) : 1
  return {
    id: 'model-tier-mismatch',
    title: 'Oversized model for a trivial step',
    category: 'cost',
    score,
    weight: 1,
    savings: { usd: round(saved) },
    findings,
    hint: 'Route trivial steps (routing, classification, short extraction) to a cheaper model tier; reserve the frontier model for hard reasoning.',
  }
}

