/** Normalize a model id for matching: lowercase, drop provider prefix + date/`latest` suffixes. */
export function normalizeModelId(id: string): string {
  return id
    .toLowerCase()
    .replace(/^(anthropic|openai|google|vertex_ai|azure|us|eu)[._/]/, '')
    .replace(/[-@](\d{6,8}|latest|preview|v\d+)$/, '')
    .trim()
}

/**
 * A resolvable price table. Matching is forgiving: exact normalized match,
 * then alias/substring match in either direction, so `claude-opus-4-8-20250101`
 * and `anthropic.claude-sonnet-4-6` both resolve.
 */
export class Pricing {
  readonly models: ModelPrice[]
  private readonly byId: Map<string, ModelPrice>

  constructor(models: ModelPrice[] = DEFAULT_MODELS) {
    this.models = models
    this.byId = new Map(models.map((m) => [normalizeModelId(m.id), m]))
  }

  /** Resolve a model id to its price entry, or undefined if unknown. */
  find(model?: string): ModelPrice | undefined {
    if (!model) return undefined
    const norm = normalizeModelId(model)
    const exact = this.byId.get(norm)
    if (exact) return exact
    for (const m of this.models) {
      const mid = normalizeModelId(m.id)
      if (norm.includes(mid) || mid.includes(norm)) return m
      if (m.aliases?.some((a) => norm.includes(normalizeModelId(a)) || normalizeModelId(a).includes(norm))) return m
    }
    return undefined
  }

  /** Tier of a model, or undefined if unknown. */
  tierOf(model?: string): ModelTier | undefined {
    return this.find(model)?.tier
  }

  /** The cheaper comparable model for a given model, if one is registered. */
  cheaperAlternative(model?: string): ModelPrice | undefined {
    const entry = this.find(model)
    if (!entry?.cheaperAlternative) return undefined
    return this.find(entry.cheaperAlternative)
  }

  /** Estimate the USD cost of a token usage on a given model. Returns 0 if unknown. */
  estimateUsage(usage: TokenUsage | undefined, model?: string): number {
    const price = this.find(model)
    if (!price || !usage) return 0
    const cachedInput = price.cachedInput ?? price.input * 0.1
    const cacheWrite = price.cacheWrite ?? price.input * 1.25
    const input = usage.input ?? 0
    const output = usage.output ?? 0
    const cacheRead = usage.cacheRead ?? 0
    const cacheWritten = usage.cacheWrite ?? 0
    return (
      (input * price.input +
        output * price.output +
        cacheRead * cachedInput +
        cacheWritten * cacheWrite) /
      1_000_000
    )
  }

  /**
   * Cost of an LLM span in USD. Prefers a cost the source already reported;
   * otherwise estimates from token usage and the price table.
   */
  costOf(span: Span): number {
    if (typeof span.cost === 'number') return span.cost
    return this.estimateUsage(span.usage, span.model)
  }
}

/** A shared default-priced instance. */
export const defaultPricing = new Pricing()

/**
 * Vercel AI SDK adapter. The AI SDK's `experimental_telemetry` emits OTLP spans
 * with `ai.*` attributes. It records a wrapper span (`ai.generateText`) plus a
 * child provider span (`ai.generateText.doGenerate`); both carry token usage, so
 * we treat the `.doGenerate` / `.doStream` leaves as the LLM calls and the
 * wrappers as chain spans to avoid double-counting tokens.
 */
import type { AgentRun, Span, SpanKind, TokenUsage } from '../../trace/types.js'
import { buildRun } from '../../trace/index.js'
import { flattenOtlp, isOtlp, type RawOtelSpan } from '../otlp.js'
import { num, str } from '../genai.js'

/** True if this looks like a Vercel AI SDK OTLP trace (`ai.*` attributes). */
export function detect(json: unknown): boolean {
  if (!isOtlp(json)) return false
  return flattenOtlp(json).some((s) => Object.keys(s.attributes).some((k) => k.startsWith('ai.')))
}

function aiUsage(a: Record<string, unknown>): TokenUsage | undefined {
  const input = num(a['ai.usage.promptTokens'] ?? a['ai.usage.inputTokens'] ?? a['gen_ai.usage.input_tokens'])
  const output = num(a['ai.usage.completionTokens'] ?? a['ai.usage.outputTokens'] ?? a['gen_ai.usage.output_tokens'])
  const cacheRead = num(a['ai.usage.cachedInputTokens'] ?? a['gen_ai.usage.cache_read_input_tokens'])
  if (input === undefined && output === undefined && cacheRead === undefined) return undefined
  const usage: TokenUsage = {}
  if (input !== undefined) usage.input = input
  if (output !== undefined) usage.output = output
  if (cacheRead !== undefined) usage.cacheRead = cacheRead
  return usage
}

function classify(name: string, a: Record<string, unknown>, hasLeafCalls: boolean): SpanKind {
  if (name === 'ai.toolCall' || a['ai.toolCall.name'] !== undefined) return 'tool'
  if (/\.do(Generate|Stream)$/.test(name)) return 'llm'
  if (/\.doEmbed$/.test(name) || name === 'ai.embed' || name === 'ai.embedMany') return 'retrieval'
  const isWrapper = /^ai\.(generateText|streamText|generateObject|streamObject)$/.test(name)
  if (isWrapper) return hasLeafCalls ? 'chain' : 'llm'
  if (a['ai.model.id'] !== undefined) return 'llm'
  return 'unknown'
}

function provider(a: Record<string, unknown>): string | undefined {
  const p = str(a['ai.model.provider'] ?? a['gen_ai.system'])
  // e.g. "anthropic.messages" -> "anthropic"
  return p ? p.split('.')[0] : undefined
}

/** Parse a Vercel AI SDK OTLP trace into a normalized {@link AgentRun}. */
export function parse(json: unknown): AgentRun {
  const raw = flattenOtlp(json)
  const hasLeafCalls = raw.some((s) => /\.do(Generate|Stream)$/.test(s.name))
  const spans: Span[] = raw.map((r: RawOtelSpan) => {
    const a = r.attributes
    const kind = classify(r.name, a, hasLeafCalls)
    const span: Span = {
      id: r.spanId,
      parentId: r.parentSpanId,
      name: str(a['ai.operationId']) ?? r.name,
      kind,
      startTime: r.startTime,
      endTime: r.endTime,
      attributes: a,
    }
    if (r.statusCode === 2) span.status = 'error'
    else if (r.statusCode === 1) span.status = 'ok'

    if (kind === 'llm' || kind === 'retrieval') {
      const model = str(a['ai.model.id'] ?? a['gen_ai.request.model'])
      if (model) span.model = model
      const prov = provider(a)
      if (prov) span.provider = prov
      const usage = aiUsage(a)
      if (usage) span.usage = usage
    }
    if (kind === 'tool') {
      const toolName = str(a['ai.toolCall.name']) ?? r.name
      span.toolName = toolName
      if (a['ai.toolCall.args'] !== undefined) span.input = a['ai.toolCall.args']
      if (a['ai.toolCall.result'] !== undefined) span.output = a['ai.toolCall.result']
    } else {
      if (a['ai.prompt'] !== undefined) span.input = a['ai.prompt']
      if (a['ai.response.text'] !== undefined) span.output = a['ai.response.text']
    }
    if (r.statusMessage && span.status === 'error') span.error = r.statusMessage
    return span
  })
  const name = raw.map((s) => str(s.resource['service.name'])).find(Boolean)
  return buildRun(spans, { source: 'vercel', name })
}

