import type { Span } from '../src/trace/types.js'
import { buildRun } from '../src/trace/index.js'

let counter = 0

/** Create a span with sensible defaults; override anything via `partial`. */
export function span(partial: Partial<Span> = {}): Span {
  counter += 1
  const startTime = partial.startTime ?? 0
  const endTime = partial.endTime ?? startTime + 100
  return {
    id: partial.id ?? `span-${counter}`,
    name: partial.name ?? 'span',
    kind: partial.kind ?? 'unknown',
    startTime,
    endTime,
    attributes: partial.attributes ?? {},
    ...partial,
  }
}

/** Create an LLM span. */
export function llm(partial: Partial<Span> = {}): Span {
  return span({ kind: 'llm', name: 'llm', model: 'claude-opus-4-8', provider: 'anthropic', ...partial })
}

/** Create a tool span. */
export function tool(name: string, partial: Partial<Span> = {}): Span {
  return span({ kind: 'tool', name, toolName: name, ...partial })
}

/** Build a run from spans. */
export function run(spans: Span[]) {
  return buildRun(spans, { source: 'test' })
}

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
