    expect(run.source).toBe(source)
    const report = audit(run)
    expect(report.audits).toHaveLength(7)
    expect(report.score).toBeGreaterThanOrEqual(0)
    expect(report.score).toBeLessThanOrEqual(100)
  })
})

describe('before/after demo', () => {
  const naive = audit(load('before-after/naive.json'))
  const optimized = audit(load('before-after/optimized.json'))

  it('the optimized run scores meaningfully higher', () => {
    expect(optimized.score - naive.score).toBeGreaterThanOrEqual(20)
    expect(optimized.score).toBeGreaterThanOrEqual(85)
  })

  it('the optimized run is dramatically cheaper (the headline)', () => {
    expect(optimized.run.totalCostUsd).toBeLessThan(naive.run.totalCostUsd * 0.25)
  })

  it('the optimized run is cheaper and faster', () => {
    expect(optimized.run.totalCostUsd).toBeLessThan(naive.run.totalCostUsd)
    expect(optimized.run.durationMs).toBeLessThan(naive.run.durationMs)
  })

  it('the naive run surfaces the headline inefficiencies', () => {
    const failing = new Set(naive.audits.filter((a) => a.findings.length).map((a) => a.id))
    expect(failing).toContain('duplicate-tool-calls')
    expect(failing).toContain('model-tier-mismatch')
    expect(failing).toContain('parallelizable-tool-calls')
    expect(failing).toContain('errors')
    expect(failing).toContain('uncacheable-prompts')
  })

  it('the optimized run clears those inefficiencies', () => {
    const failing = new Set(optimized.audits.filter((a) => a.findings.length).map((a) => a.id))
    expect(failing.has('duplicate-tool-calls')).toBe(false)
    expect(failing.has('model-tier-mismatch')).toBe(false)
    expect(failing.has('errors')).toBe(false)
  })
})

