import { describe, it, expect } from 'vitest'
import {
  spanDuration,
  runDuration,
  spansByKind,
  llmSpans,
  toolSpans,
  childrenOf,
  rootSpans,
  totalTokens,
  buildRun,
} from './index.js'
import { span, llm, tool } from '../../test/helpers.js'

describe('trace helpers', () => {
  it('computes span duration and clamps negatives to zero', () => {
    expect(spanDuration(span({ startTime: 100, endTime: 350 }))).toBe(250)
    expect(spanDuration(span({ startTime: 500, endTime: 400 }))).toBe(0)
  })

  it('derives the run window from span timestamps', () => {
    const r = buildRun([
      span({ startTime: 200, endTime: 300 }),
      span({ startTime: 0, endTime: 150 }),
      span({ startTime: 100, endTime: 500 }),
    ])
    expect(r.startTime).toBe(0)
    expect(r.endTime).toBe(500)
    expect(runDuration(r)).toBe(500)
  })

  it('sorts spans by start time', () => {
    const r = buildRun([
      span({ id: 'b', startTime: 200 }),
      span({ id: 'a', startTime: 0 }),
    ])
    expect(r.spans.map((s) => s.id)).toEqual(['a', 'b'])
  })

  it('filters spans by kind', () => {
    const r = buildRun([llm(), tool('search'), tool('fetch')])
    expect(llmSpans(r)).toHaveLength(1)
    expect(toolSpans(r)).toHaveLength(2)
    expect(spansByKind(r, 'agent')).toHaveLength(0)
  })

  it('resolves parent/child and root relationships', () => {
    const r = buildRun([
      span({ id: 'root' }),
      span({ id: 'child1', parentId: 'root' }),
      span({ id: 'child2', parentId: 'root' }),
      span({ id: 'orphan', parentId: 'missing' }),
    ])
    expect(childrenOf(r, 'root').map((s) => s.id)).toEqual(['child1', 'child2'])
    // orphan's parent is absent, so it counts as a root
    expect(rootSpans(r).map((s) => s.id).sort()).toEqual(['orphan', 'root'])
  })

  it('sums token usage across llm spans, preferring explicit totals', () => {
    const r = buildRun([
      llm({ usage: { input: 100, output: 50 } }),
      llm({ usage: { total: 999, input: 1, output: 1 } }),
      tool('noop'),
    ])
    expect(totalTokens(r)).toBe(150 + 999)
  })

  it('produces an empty window for an empty run', () => {
    const r = buildRun([])
    expect(r.startTime).toBe(0)
    expect(r.endTime).toBe(0)
    expect(runDuration(r)).toBe(0)
  })
})

import { describe, it, expect } from 'vitest'
import { score, DEFAULT_WEIGHTS } from './index.js'
import type { AuditResult, AuditCategory } from '../audit/index.js'

function a(category: AuditCategory, s: number, weight = 1): AuditResult {
  return { id: `${category}-${s}`, title: 't', category, score: s, weight, savings: {}, findings: [], hint: '' }
}

describe('score', () => {
  it('computes category scores as weighted averages of audit scores', () => {
    const result = score([a('cost', 1), a('cost', 0)])
    const cost = result.categories.find((c) => c.category === 'cost')!
    expect(cost.score).toBe(50)
  })

  it('respects per-audit weights', () => {
    const result = score([a('cost', 1, 3), a('cost', 0, 1)])
    expect(result.categories[0]!.score).toBe(75)
  })

  it('computes overall as the category-weighted average', () => {
    const result = score([
      a('cost', 1), // 100
      a('latency', 0.5), // 50
      a('reliability', 1), // 100
      a('context', 0), // 0
    ])
    // 0.3*100 + 0.3*50 + 0.2*100 + 0.2*0 = 30+15+20+0 = 65
    expect(result.overall).toBe(65)
  })

  it('renormalizes when a category is absent', () => {
    const result = score([a('cost', 1), a('latency', 0)])
    // weights 0.3 / 0.3 -> (100*0.3 + 0*0.3)/0.6 = 50
    expect(result.overall).toBe(50)
  })

  it('returns a perfect score for an all-clean run', () => {
    const result = score([a('cost', 1), a('latency', 1), a('reliability', 1), a('context', 1)])
    expect(result.overall).toBe(100)
  })

  it('exposes the default weights', () => {
    expect(DEFAULT_WEIGHTS.cost + DEFAULT_WEIGHTS.latency + DEFAULT_WEIGHTS.reliability + DEFAULT_WEIGHTS.context).toBeCloseTo(1)
  })
})
